HEALTHY = {
    "Apple___healthy": ("Apple", "सेब"), "Blueberry___healthy": ("Blueberry", "ब्लूबेरी"),
    "Cherry_(including_sour)___healthy": ("Cherry", "चेरी"), "Corn_(maize)___healthy": ("Corn (Maize)", "मक्का"),
    "Grape___healthy": ("Grape", "अंगूर"), "Peach___healthy": ("Peach", "आड़ू"),
    "Pepper,_bell___healthy": ("Bell pepper", "शिमला मिर्च"), "Potato___healthy": ("Potato", "आलू"),
    "Raspberry___healthy": ("Raspberry", "रसभरी"), "Soybean___healthy": ("Soybean", "सोयाबीन"),
    "Strawberry___healthy": ("Strawberry", "स्ट्रॉबेरी"), "Tomato___healthy": ("Tomato", "टमाटर"),
}
for k, (en, hi) in HEALTHY.items():
    KB[k] = healthy(en, hi)

missing = [c for c in CLASS_NAMES if c not in KB]
assert not missing, missing
out = {c: KB[c] for c in CLASS_NAMES}
path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data", "knowledge_base.json")
json.dump(out, open(path, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
print("wrote", path, len(out), "classes")
